(177, 'location_pool', 'workflow', '["уединенный особняк на скале у моря", "плавучее казино на реке", "горнолыжное шале, отрезанное снежной бурей", "бродячий цирк-шапито на гастролях", "старинный маяк на отдаленном острове", "ночной поезд дальнего следования", "заброшенная киностудия", "ботанический сад с оранжереей", "антикварный аукционный дом", "винодельня в горах", "частная яхта в открытом море", "загородный охотничий домик", "закулисье театра во время премьеры", "санаторий на горячих источниках", "букинистический магазин с потайными комнатами", "обсерватория на вершине холма", "ресторан высокой кухни в подвале старого здания", "оранжерея-ферма экзотических бабочек", "частная библиотека-архив редких книг", "заброшенный монастырь, переоборудованный в отель"]', 'Пул тем места преступления для случайного выбора'),
(178, 'weapon_pool', 'workflow', '["отравленный бокал вина", "удушение шарфом", "подстроенное падение с высоты", "редкий яд, подмешанный в лекарство", "удар тяжелой статуэткой", "утопление в бассейне", "удушающий газ в закрытом помещении", "удар током от подстроенной проводки", "отравленное блюдо с ядовитыми грибами", "удавка из струны музыкального инструмента", "смертельная аллергическая реакция, подстроенная умышленно", "огнестрельное оружие из частной коллекции", "несчастный случай с механизмом лифта", "удар веслом", "отравленный чай", "передозировка снотворного", "удушение подушкой во сне", "яд экзотического животного", "перерезанный трос или тормоза", "удар тяжелым подсвечником"]', 'Пул тем орудия убийства для случайного выбора'),
